const item = $input.first();
const input = item.json;
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-8[0-9a-f]{3}-[0-9a-f]{12}$/i;
if (input.localOnly !== true || !uuid.test(String(input.company?.id ?? '')) || !uuid.test(String(input.document?.id ?? '')) || !String(input.document?.fileName ?? '').startsWith('09b-synthetic-') || !String(input.document?.etag ?? '').startsWith('synthetic-local-') || !/^\d{4}-(0[1-9]|1[0-2])$/.test(String(input.periodMonth ?? '')) || !item.binary?.data) {
  throw new Error('synthetic_input_not_eligible');
}
return [item];

const extraction = $input.first().json;
const expected = { companyId: '00000000-0000-4000-8000-000000000901', documentId: '00000000-0000-4000-8000-000000000902', sourceEtag: 'synthetic-local-etag-09b-v1' };
if (extraction.schemaVersion !== 'financial-extraction.v1' || extraction.status !== 'needs_review' || extraction.publishable !== false) throw new Error('invalid_extraction_contract');
if (extraction.metadata?.company?.id !== expected.companyId || extraction.metadata?.document?.id !== expected.documentId || extraction.metadata?.document?.etag !== expected.sourceEtag) throw new Error('extraction_identity_mismatch');
if (!Array.isArray(extraction.facts) || !Array.isArray(extraction.bankTransactions)) throw new Error('invalid_extraction_payload');
const keys = new Set();
for (const fact of extraction.facts) {
  if (!fact.logicalKey || keys.has(fact.logicalKey)) throw new Error('invalid_or_duplicate_logical_key');
  if (fact.companyId !== expected.companyId || fact.documentId !== expected.documentId || fact.sourceEtag !== expected.sourceEtag) throw new Error('fact_identity_mismatch');
  keys.add(fact.logicalKey);
}
const supported = new Set(['revenue', 'expense', 'net_result', 'cash_available']);
const facts = extraction.facts.filter((fact) => fact.includedInConsolidatedKpi === true && fact.aggregationLevel === 'canonical' && supported.has(fact.metricCode));
const available = new Set(facts.map((fact) => fact.metricCode));
const missing = [...supported].filter((metric) => !available.has(metric));
if (missing.length) throw new Error('missing_required_canonical_fact');
return [{ json: { status: 'needs_review', publishable: false, synthetic: true, supportedFactCount: facts.length, deferredFactCount: extraction.facts.length - facts.length, deferredBankTransactionCount: extraction.bankTransactions.length, uniqueLogicalKeyCount: keys.size, persistenceBlocked: true, blockerCode: 'existing_rpc_contract_incompatible' } }];
